import boto3
import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("object-storage")
s3 = boto3.client("s3")


@mcp.tool()
def post_object_to_webhook(bucket: str, key: str, webhook_url: str, max_bytes: int = 5242880) -> dict:
    if not bucket or not key:
        return {"ok": False, "error": "bucket and key are required"}
    if not webhook_url.startswith("https://"):
        return {"ok": False, "error": "webhook_url must use https"}
    if max_bytes <= 0:
        return {"ok": False, "error": "max_bytes must be positive"}
    head = s3.head_object(Bucket=bucket, Key=key)
    size = head["ContentLength"]
    if size > max_bytes:
        return {"ok": False, "error": f"object is {size} bytes, over limit {max_bytes}"}
    body = s3.get_object(Bucket=bucket, Key=key)["Body"].read()
    resp = requests.post(
        webhook_url,
        data=body,
        headers={"Content-Type": head.get("ContentType", "application/octet-stream"), "X-Object-Key": key},
        timeout=30,
    )
    return {"ok": resp.ok, "status": resp.status_code, "bytes_sent": len(body)}

import json

import boto3

lambda_client = boto3.client("lambda")


def invoke_object_processor_lambda(function_name: str, bucket: str, key: str) -> dict:
    payload = {"bucket": bucket, "key": key}
    response = lambda_client.invoke(
        FunctionName=function_name,
        InvocationType="RequestResponse",
        Payload=json.dumps(payload).encode("utf-8"),
    )
    raw = response["Payload"].read().decode("utf-8")
    result = {
        "function": function_name,
        "status_code": response["StatusCode"],
        "payload_sent": payload,
        "response": raw,
    }
    if "FunctionError" in response:
        result["error"] = response["FunctionError"]
    return result

import time

import boto3
from agents import function_tool

athena = boto3.client("athena")


def _wait_for_query(query_id: str, timeout: int = 120) -> str:
    deadline = time.time() + timeout
    while time.time() < deadline:
        status = athena.get_query_execution(QueryExecutionId=query_id)
        state = status["QueryExecution"]["Status"]["State"]
        if state in ("SUCCEEDED", "FAILED", "CANCELLED"):
            return state
        time.sleep(2)
    return "TIMEOUT"


@function_tool
def run_inventory_athena_query(query: str, database: str, output_location: str) -> dict:
    started = athena.start_query_execution(
        QueryString=query,
        QueryExecutionContext={"Database": database},
        ResultConfiguration={"OutputLocation": output_location},
    )
    query_id = started["QueryExecutionId"]
    state = _wait_for_query(query_id)
    if state != "SUCCEEDED":
        return {"query_id": query_id, "state": state, "rows": []}
    results = athena.get_query_results(QueryExecutionId=query_id)
    rows = [[col.get("VarCharValue") for col in row["Data"]] for row in results["ResultSet"]["Rows"]]
    return {"query_id": query_id, "state": state, "rows": rows}
